import { id, notebook, page, duplicateNotebook } from './model.js';
export function trashNotebook(state,bookId){const index=state.notebooks.findIndex(n=>n.id===bookId);if(index<0)return;const [book]=state.notebooks.splice(index,1);state.trash??=[];state.trash.unshift({id:id(),kind:'notebook',deletedAt:Date.now(),data:book});}
export function trashPage(state,bookId,pageId){const book=state.notebooks.find(n=>n.id===bookId);if(!book)return;const index=book.pages.findIndex(p=>p.id===pageId);if(index<0)return;const [data]=book.pages.splice(index,1);state.trash??=[];state.trash.unshift({id:id(),kind:'page',deletedAt:Date.now(),bookId,bookTitle:book.title,index,data});if(!book.pages.length)book.pages.push(page());book.updatedAt=Date.now();return book.pages[Math.min(index,book.pages.length-1)].id;}
export function restoreItem(state,entryId){const index=(state.trash||[]).findIndex(e=>e.id===entryId);if(index<0)return;const entry=state.trash[index];let book;if(entry.kind==='notebook'){book=duplicateNotebook(entry.data);book.title=entry.data.title;if(!state.collections.some(c=>c.id===book.collection))book.collection=null;state.notebooks.push(book);}else{book=state.notebooks.find(n=>n.id===entry.bookId);if(!book){book=notebook(entry.bookTitle||'Recovered pages');book.pages=[];state.notebooks.push(book);}book.pages.splice(Math.min(entry.index,book.pages.length),0,{...structuredClone(entry.data),id:id(),updatedAt:Date.now()});book.updatedAt=Date.now();}state.trash.splice(index,1);return book;}
export function matchingPages(book,query){const q=query.trim().toLocaleLowerCase();return book.pages.filter(p=>!q||`${p.title}\n${p.text}`.toLocaleLowerCase().includes(q));}
export function resumePage(book){return book.pages.find(p=>p.id===book.lastPageId)||book.pages[0];}
